/* crosswalk cards, r39. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39a"]=[{"q": "On {0, 1}, the mark of “both x and y” is which?", "a": "xy", "w": ["x + y", "the greater of x and y", "x + y − 2xy"], "why": "The and-as-product technique: the product is 1 only on the row 1, 1."}, {"q": "On {0, 1}, the mark of “at least one of x, y” is x + y − xy. Which technique?", "a": "or-as-greater", "w": ["and-as-product", "remainder-by-two", "swap-the-denial"], "why": "It is the greater of x and y, and x + y − xy equals it on all four rows."}, {"q": "On {0, 1}, the mark of “not x” is which?", "a": "1 − x", "w": ["−x", "1/x", "x − 1"], "why": "It sends 1 to 0 and 0 to 1."}, {"q": "On {0, 1}, “exactly one of x, y” is the remainder of x + y on division by what?", "a": "2", "w": ["1", "3", "x + y"], "why": "The remainder-by-two technique: 0, 1, 1, 2 leave 0, 1, 1, 0."}, {"q": "A line reads x ∨ y = x + y. Is it allowed on {0, 1}?", "a": "no: it gives 2 on the row 1, 1", "w": ["yes: the sum is the either", "yes, when x = y", "no: it gives 0 on the row 0, 0"], "why": "The either must subtract xy, which is 1 exactly where the sum overshoots."}, {"q": "x² = x holds for which numbers?", "a": "0 and 1 only", "w": ["every number", "1 only", "every whole number"], "why": "x(x − 1) = 0 has the roots 0 and 1."}, {"q": "x + y on {0, 1}, written in base two: the twos place is which mark?", "a": "xy, the and", "w": ["x ⊕ y", "the greater of x and y", "1 − x"], "why": "Only the row 1, 1 reaches 2."}, {"q": "cos 0 and cos(π/2) give which two marks?", "a": "1 and 0", "w": ["0 and 1", "1 and −1", "½ and 0"], "why": "The full share is 1, no share is 0."}, {"q": "A column reads 1, 0, 1, 1 on the rows 00, 01, 10, 11 of x, y. Which polynomial is it?", "a": "1 − y + xy", "w": ["1 − x + xy", "x + y − xy", "xy"], "why": "It is 0 only on x = 0, y = 1: the mark of “if y then x”."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39b"]=[{"q": "V cos(2πft): what is f called?", "a": "the frequency", "w": ["the size", "the period", "the start"], "why": "Turns a second, in hertz."}, {"q": "s(θ) is 1 when cos θ > 0 and 0 when cos θ < 0. What is ½ in its recipe?", "a": "its 0th turning, the average", "w": ["its first turning", "its threshold", "its margin"], "why": "The sign wave is on for half of each turn."}, {"q": "The sign-wave recipe ½ + (2/π)(cos θ − cos 3θ/3 + ⋯) uses which speeds?", "a": "the odd ones only", "w": ["every speed", "the even ones only", "speeds 1 and 3 only"], "why": "It is rung 32’s square, slid a quarter turn."}, {"q": "u = ½ + (2/π) cos θ is read against ½. What comes back?", "a": "every bit of the sign wave", "w": ["the sign wave itself", "half of the bits", "nothing: u is not a square"], "why": "The first-turning technique: u > ½ exactly when cos θ > 0."}, {"q": "Is u = ½ + (2/π) cos θ a square wave?", "a": "no: only its reading is", "w": ["yes", "yes, near θ = 0", "no: it never passes ½"], "why": "It swings smoothly from about −0.137 to 1.137."}, {"q": "What do the higher turnings of a square wave add?", "a": "sharp edges: when a change happened", "w": ["the bits", "the average", "the power of the 0th turning"], "why": "The first turning already gives back every bit."}, {"q": "A 0 sent at 0.6 V, noise spread 0.1 V, threshold 1.2 V. The misread chance is the bell beyond how many spreads?", "a": "6", "w": ["0.6", "12", "1.2"], "why": "The margin 0.6 V over the spread 0.1 V."}, {"q": "A line reads P(Z > 12) = 2 P(Z > 6). Is it allowed?", "a": "no: the tail falls far faster", "w": ["yes: twice the margin, twice as rare", "yes, for a bell", "no: P(Z > 12) is larger"], "why": "About 10⁻³³ against 10⁻⁹."}, {"q": "Reading a wire against a threshold makes the reading wrong at what?", "a": "a known rate", "w": ["no rate: it is exact", "an unknown rate", "half the time"], "why": "Laws with a known exception rate: the error is exact, not zero."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39c"]=[{"q": "The average square of a wave is the sum of the average squares of its turnings. Which technique?", "a": "power-by-frequency", "w": ["changes-per-second", "known-wave", "sign-wave"], "why": "It is the energy-kept technique of rung 32, read as power."}, {"q": "A 120 V socket runs a 1500 W kettle. How many bits does the socket’s wave carry?", "a": "0", "w": ["60 a second", "120 a second", "1500 a second"], "why": "The known-wave technique: a wave fixed by known numbers says nothing."}, {"q": "A square wave whose 1s and 0s come from a coin carries how much at each change?", "a": "1 bit", "w": ["0 bits", "2 bits", "as much as its power"], "why": "Each change chooses between two."}, {"q": "A wire passes frequencies up to B. How many free values a second can it carry?", "a": "2B", "w": ["B", "B/2", "4B"], "why": "The changes-per-second technique: samples at the spacing 1/(2B) are free."}, {"q": "With M levels at each change, the wire carries at most how many bits a second?", "a": "2B log₂ M", "w": ["B log₂ M", "2BM", "M log₂ 2B"], "why": "M^(2B) patterns a second, and the log of a power."}, {"q": "An old phone line: B = 3100 Hz, S/N = 3000. About how many bits a second?", "a": "35 800", "w": ["6200", "9 300 000", "3100"], "why": "B log₂(1 + S/N) = 3100 log₂ 3001."}, {"q": "The sign wave of size V: average square ½V², square of average ¼V². Which carries the swinging power?", "a": "the turnings past the 0th", "w": ["the 0th turning alone", "neither", "the threshold"], "why": "The average square is not the square of the average."}, {"q": "Once S/N is large, doubling the signal power adds about how much to each change?", "a": "half a bit", "w": ["one bit", "twice the bits", "nothing"], "why": "Each change carries ½ log₂(1 + S/N)."}, {"q": "A wire passing up to B: doubling B does what to the bits a second?", "a": "doubles them", "w": ["adds one bit", "adds half a bit", "nothing"], "why": "The capacity B log₂(1 + S/N) is in proportion to B."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39d"]=[{"q": "Pushed backwards, a diode passes less than Iₛ, however hard it is pushed. Which technique?", "a": "reverse-leak", "w": ["no-gain", "rising-network", "diode-gate"], "why": "e^(V/Vₜ) lies between 0 and 1 for V < 0."}, {"q": "A diode is called a switch that nobody works. What sets its state?", "a": "the sign of the push across it", "w": ["a third wire", "its resistance", "a clock"], "why": "It is closed one way and open the other."}, {"q": "A diode either gate with inputs 5 V and 0 V and a 1 kΩ load gives about what?", "a": "4.43 V", "w": ["5 V", "0.57 V", "2.5 V"], "why": "One diode drop below the higher input."}, {"q": "A diode both gate with inputs 5 V and 0 V gives about what?", "a": "0.6 V, read as 0", "w": ["4.4 V, read as 1", "0 V exactly", "2.5 V"], "why": "The lower input wins, one drop up."}, {"q": "In a network of diodes and resistors, raising inputs never lowers a node. Which technique?", "a": "rising-network", "w": ["no-gain", "reverse-leak", "pair-inverter"], "why": "Each part’s current rises with the voltage across it."}, {"q": "Can a network of diodes and resistors make a not?", "a": "no", "w": ["yes, with enough diodes", "yes, with a large resistor", "only at 5 V"], "why": "A not lowers its output when its input rises."}, {"q": "Five either gates in a row: 5, 4.43, 3.86, 3.29, 2.73, then about 2.2 V. Read against 2.5 V, the last reads what?", "a": "0", "w": ["1", "neither", "the first input"], "why": "The no-gain technique: valves never win back a lost drop."}, {"q": "If no input rises by more than Δ, no node rises by more than Δ. What does that forbid?", "a": "restoring a weak level", "w": ["making a both", "making an either", "passing current forward"], "why": "Restoring needs a slope above 1 near the threshold."}, {"q": "A line reads “a diode is a resistor of about 0.6/I Ω”. Is it allowed?", "a": "no: its current is exponential", "w": ["yes", "yes, forward only", "no: it is 0.6 Ω always"], "why": "Tenfold for each 60 mV."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39e"]=[{"q": "A switch to ground that closes on high, a switch to the supply that closes on low, gates joined. What does it make?", "a": "a not", "w": ["a both", "an either", "a memory"], "why": "The pair-inverter technique: the output is 1 − x."}, {"q": "Why does the pair inverter escape the rising-network technique?", "a": "its switches are set by a third wire", "w": ["it has no resistors", "it uses diodes backwards", "it has no supply"], "why": "Raising the gate shuts the path to the supply."}, {"q": "Two not gates in a row, G = g ∘ g. What is G′(m) at the middle rest?", "a": "g′(m)²", "w": ["2g′(m)", "g′(m)", "1"], "why": "The chain rule, with g(m) = m."}, {"q": "|g′(m)| > 1 at the middle. What does the middle rest of a pair do?", "a": "pushes nearby voltages away", "w": ["holds", "pulls them in", "nothing"], "why": "The middle-gain technique."}, {"q": "g′(m) = −3.3. Near the rails the pair’s slope is about 0.0003. What do the end rests do?", "a": "hold, hard", "w": ["push", "run round", "drift to the middle"], "why": "A curve steep in the middle is flat at the ends."}, {"q": "Each pair adds noise η and pulls with slope k < 1 near a rail. The error never passes what?", "a": "η/(1 − k)", "w": ["nη", "η k", "η/k"], "why": "The noise-floor technique: a geometric sum."}, {"q": "A chain of valves, slope 1, noise η a stage. After n stages the error may reach what?", "a": "nη", "w": ["η", "η/(1 − k)", "η²"], "why": "With k = 1 nothing is pulled back."}, {"q": "33 µW on the gate steers 24 W to a pump. What is the ratio called?", "a": "the power gain", "w": ["the slope", "the margin", "the threshold"], "why": "The steering technique."}, {"q": "In the steering example, which of the two questions does the gate answer?", "a": "the message: when to switch", "w": ["the power: how much reaches the pump", "both", "neither"], "why": "The strip carries the power."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39f"]=[{"q": "nand(x, x) is which?", "a": "not x", "w": ["x", "x and x", "1"], "why": "1 − x² = 1 − x on {0, 1}."}, {"q": "How many not-ands make an either?", "a": "3", "w": ["1", "2", "4"], "why": "nand(¬x, ¬y), with a not-and for each not."}, {"q": "How many not-ands make a both?", "a": "2", "w": ["1", "3", "4"], "why": "The not of the not-and."}, {"q": "Every table of n inputs is (x ∧ f₁) ∨ (¬x ∧ f₀). Which technique?", "a": "split-on-one", "w": ["nand-alone", "most-tables-hard", "one-row-each"], "why": "Cases on the first input."}, {"q": "The split-on-one recipe spends at most how many gates on a table of n inputs?", "a": "5 · 2ⁿ⁻¹ − 4", "w": ["2ⁿ", "n²", "4n"], "why": "G(n) ≤ 2G(n − 1) + 4, from G(1) ≤ 1."}, {"q": "There are fewer circuits of g gates than tables of n inputs. What follows?", "a": "some table needs more than g gates", "w": ["every table needs more than g gates", "no table needs g gates", "g is at most 2ⁿ"], "why": "The most-tables-hard technique: no room."}, {"q": "How many tables of 10 inputs are there?", "a": "2^1024", "w": ["2^10", "1024", "10^1024"], "why": "A column of 2¹⁰ marks."}, {"q": "Can boths and eithers alone build every table?", "a": "no: they never give a not", "w": ["yes", "yes, with three layers", "only for two inputs"], "why": "A circuit of rising gates is rising."}, {"q": "A line reads “the recipe takes 5 · 2ⁿ⁻¹ − 4 gates, so some table needs that many”. Is it allowed?", "a": "no: that is an upper count", "w": ["yes", "yes, for n ≥ 2", "no: it is a lower count"], "why": "An upper count for one recipe says nothing about the best circuit."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39g"]=[{"q": "A not fed into itself with no delay would need x = 1 − x. What meets it?", "a": "½, which is no mark", "w": ["0", "1", "nothing at all"], "why": "The liar’s point: no mark meets it."}, {"q": "A not fed into itself with a delay τ: what is the period of its output?", "a": "2τ", "w": ["τ", "4τ", "τ/2"], "why": "The delay-loop technique: 1 for τ, then 0 for τ."}, {"q": "A ring of an odd number of nots has how many rests?", "a": "one, the middle, which does not hold", "w": ["none", "two that hold", "one that holds"], "why": "The odd-ring technique."}, {"q": "A ring of 3 nots, each with delay 10 ps. Its period?", "a": "60 ps", "w": ["30 ps", "20 ps", "10 ps"], "why": "The ring-period technique: 2nτ."}, {"q": "Why is the period of an odd ring 2nτ and not nτ?", "a": "after one trip the change comes back turned over", "w": ["each gate waits twice", "the clock counts both edges", "the delay doubles in a ring"], "why": "An odd count of nots is a not."}, {"q": "A line reads “the liar box is stuck at ½”. Is it allowed?", "a": "no: ½ does not hold, it runs", "w": ["yes", "yes, for slow gates", "no: it is stuck at 0"], "why": "Its one rest pushes."}, {"q": "A ring of 101 gates runs at 330 MHz. What does that measure?", "a": "the delay of each gate", "w": ["the supply voltage", "the noise", "the number of bits held"], "why": "τ = 1/(2nf)."}, {"q": "An odd number of falling gates in a ring makes the once-round map what?", "a": "falling", "w": ["rising", "flat", "steep at the ends"], "why": "A fall after a fall is a rise; odd falls leave a fall."}, {"q": "Is a ring of 4 nots a clock?", "a": "no: it may rest", "w": ["yes", "yes, of period 8τ", "only with slow gates"], "why": "An even count of nots cancels."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39h"]=[{"q": "A ring of two nots with |g′(m)| > 1 has which rests that hold?", "a": "the two patterns of 1 and 0", "w": ["the middle only", "none", "all four patterns"], "why": "The even-ring technique."}, {"q": "In an even ring, what picks which pattern it holds?", "a": "its history", "w": ["its logic", "the supply", "the threshold"], "why": "x = x is met by both marks."}, {"q": "A latch of two not-ands with both doors at 1 does what?", "a": "keeps its bit", "w": ["sets Q to 1", "clears Q", "runs as a clock"], "why": "The hold-row technique: an even ring."}, {"q": "A latch with s = 0 and r = 1 does what?", "a": "sets Q to 1", "w": ["clears Q to 0", "keeps its bit", "gives Q = P = 1"], "why": "nand(0, P) = 1 whatever P was."}, {"q": "Why is the row s = r = 0 kept out?", "a": "it gives Q = P = 1, and on release both race", "w": ["it clears and sets at once", "it burns the gates", "it runs as a clock"], "why": "It is not a bit."}, {"q": "Two gated latches, the first open while c = 0 and the second while c = 1. What do they catch?", "a": "d at the rise of c", "w": ["d whenever it changes", "d at the fall of c", "the last value of c"], "why": "The edge-catch technique."}, {"q": "A row of 64 catches on one clock holds how many patterns?", "a": "2⁶⁴", "w": ["64", "64²", "2 · 64"], "why": "The register-count technique: the product rule."}, {"q": "A line reads “a gated latch catches d at one instant”. Is it allowed?", "a": "no: it follows d while its door is open", "w": ["yes", "yes, if the clock is fast", "no: it never follows d"], "why": "Two in a row catch an instant."}, {"q": "A circuit with no loop: do its outputs depend on its history?", "a": "no: only on its present inputs", "w": ["yes", "only for even counts of gates", "only while the clock is 1"], "why": "Memory needs a loop."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39i"]=[{"q": "x + y + c = 2 · (at least two of x, y, c) + which?", "a": "x ⊕ y ⊕ c", "w": ["xyc", "x ∨ y ∨ c", "x + y"], "why": "The three-bit-sum technique."}, {"q": "A line reads “carry out = x ∨ y ∨ c”. Is it allowed?", "a": "no: the carry is at least two", "w": ["yes", "yes, with c = 0", "no: the carry is xyc"], "why": "“At least one” is not “at least two”."}, {"q": "In a chain of n places, the last carry may wait how long?", "a": "2nτ", "w": ["nτ", "2τ", "τ log₂ n"], "why": "The carry-delay technique: a both then an either per place."}, {"q": "Combining (make, pass) pairs does not depend on grouping. What does that allow?", "a": "a carry tree about log₂ n levels deep", "w": ["a shorter chain", "fewer gates", "subtraction"], "why": "The carry-tree technique."}, {"q": "A 64-place carry tree has how many levels?", "a": "6", "w": ["64", "8", "32"], "why": "64 halves to 1 in six steps."}, {"q": "In 8 places, −9 is written as which?", "a": "11110111", "w": ["11110110", "10001001", "00001001"], "why": "Every bit of 9 turned over, plus 1: 256 − 9 = 247."}, {"q": "127 + 1 in 8 signed places reads what?", "a": "−128", "w": ["128", "0", "−127"], "why": "The answer is out of range and wraps round."}, {"q": "1011 + 0110 = ?", "a": "10001", "w": ["1101", "10011", "1111"], "why": "11 + 6 = 17."}, {"q": "Two numbers of the same sign give a sum of the other sign. What happened?", "a": "a wrap: the true sum is out of range", "w": ["nothing: it is right", "a carry was lost inside", "the top bit is unused"], "why": "The sign test."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39j"]=[{"q": "On the list machine, what does the instruction 290 do?", "a": "adds cell 90 to A", "w": ["stores A in cell 90", "loads cell 90 into A", "jumps to cell 90"], "why": "First digit 2 is add; the last two name the cell."}, {"q": "What does the instruction 509 do?", "a": "jumps to cell 9 if A is 0", "w": ["jumps to cell 9", "takes cell 9 from A", "stops"], "why": "First digit 5: jump if zero."}, {"q": "What makes 290 an instruction rather than data?", "a": "the counter points at its cell", "w": ["its first digit", "its size", "the cell it sits in being below 10"], "why": "In cell 90 the same number would be read as data."}, {"q": "The machine’s state is its counter, accumulator and memory, and each turn is a function of it. Which technique?", "a": "fetch-run", "w": ["instruction-number", "stored-list", "loop-count"], "why": "So a run is fixed by its first state."}, {"q": "The multiply program takes how many turns for a count k?", "a": "9k + 3", "w": ["9k", "3k + 9", "k + 3"], "why": "Nine a round, then a last test, jump and stop."}, {"q": "Why must a cell hold 1 in the multiply program?", "a": "take away works only with a cell", "w": ["to stop the machine", "to start the count", "to mark the product"], "why": "There is no “take away 1” instruction."}, {"q": "A program writes 291 into the cell that held 290. What has happened?", "a": "the program has rewritten itself", "w": ["a fault", "the data changed only", "the machine stopped"], "why": "The stored-list technique: instructions are numbers in memory."}, {"q": "When does the counter move on: before or after the instruction runs?", "a": "before", "w": ["after", "only after a jump", "never; jumps move it"], "why": "A jump then overwrites it."}, {"q": "A line reads “a processor is cleverer than a table”. Is it allowed?", "a": "no: each turn is a table applied again", "w": ["yes", "yes, with jumps", "no: it is a single table, once"], "why": "Gates compute only tables of the bits held."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39k"]=[{"q": "A loop body of 5 turns runs n times, with 2 turns outside. The count?", "a": "5n + 2", "w": ["5n", "7n", "5 + 2n"], "why": "The loop-count technique: br + s."}, {"q": "A search finds a match in the first cell in one turn. Is its count O(1)?", "a": "no: the count is over the worst input", "w": ["yes", "yes, on average", "only for small n"], "why": "The worst input of size n takes 5n + 2."}, {"q": "Each turn of one machine takes at most c turns of another. What survives?", "a": "the family O(f(n))", "w": ["the exact count", "the constant", "nothing"], "why": "The machine-change technique."}, {"q": "n = 10⁶ at 10⁹ turns a second: ½n² against n log₂ n. About how long each?", "a": "500 s and 0.02 s", "w": ["5 s and 2 s", "500 s and 20 s", "0.5 s and 0.02 s"], "why": "The ranks of 22k, in seconds."}, {"q": "A machine 1000 times faster, same time, count n². How much larger a problem?", "a": "about 31.6 times", "w": ["1000 times", "10 items larger", "2 times"], "why": "√1000."}, {"q": "A machine 1000 times faster, same time, count 2ⁿ. How much larger a problem?", "a": "about 10 items larger", "w": ["1000 times", "31.6 times", "2 items larger"], "why": "log₂ 1000 ≈ 9.97."}, {"q": "n items, each one of 2ᵇ patterns, need at least how many bits?", "a": "nb", "w": ["n + b", "b", "2ⁿᵇ"], "why": "The storage-count technique: 2ⁿᵇ lists."}, {"q": "A 3-minute song, 44 100 samples a second, 16 bits, 2 ears. About how many bytes?", "a": "31.8 million", "w": ["3.2 million", "254 million", "7.9 million"], "why": "44 100 · 16 · 2 · 180 / 8."}, {"q": "A line reads “100n is always slower than n²”. Is it allowed?", "a": "no: only below n = 100", "w": ["yes", "yes, past n = 10", "no: never"], "why": "Past 100, n² loses for ever."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39l"]=[{"q": "A search by yes-or-no questions among n places needs at least how many questions on some input?", "a": "log₂(n + 1)", "w": ["log₂ n", "n", "n/2"], "why": "The search-floor technique: n + 1 answers, “nowhere” included."}, {"q": "Halving search on a sorted list of 10⁶ takes at most how many looks?", "a": "20", "w": ["19", "1000", "10⁶"], "why": "⌊log₂ 10⁶⌋ + 1."}, {"q": "In the random-pivot sort, when are items i and j compared?", "a": "when the first pivot between them is one of them", "w": ["always", "when they are neighbours", "when one is the first pivot of the whole list"], "why": "A pivot between them parts them for good."}, {"q": "The chance that i and j are compared is 2/(j − i + 1). Which technique adds these?", "a": "pivot-chance", "w": ["search-floor", "counting-sort", "tree-depth"], "why": "The average of a count is the sum of the chances."}, {"q": "The random-pivot sort on 1000 items averages about how many comparisons?", "a": "10 986", "w": ["1 000 000", "9 966", "499 500"], "why": "2(n + 1)Hₙ − 4n."}, {"q": "A million ages below 120 are sorted by counting each value. About how many turns?", "a": "2 000 120", "w": ["18 500 000", "10¹²", "1 000 000"], "why": "Counting sort: 2n + k."}, {"q": "Counting sort makes no comparisons. Does it break the floor of 22l?", "a": "no: the floor is for sorts that only compare", "w": ["yes", "yes, for small values", "no: it compares in secret"], "why": "It learns each value outright."}, {"q": "A line reads “the random-pivot sort takes 2n ln n on every list”. Is it allowed?", "a": "no: that is its average", "w": ["yes", "yes, for sorted lists", "no: it is n log₂ n"], "why": "Its worst is n(n − 1)/2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39m"]=[{"q": "T(n) = T(n − 1) + f(n), T(1) = c. What is T(n)?", "a": "c + f(2) + ⋯ + f(n)", "w": ["n f(n)", "f(n) log n", "c + n f(n)"], "why": "The shrink-by-one technique."}, {"q": "T(n) = T(n − 1) + (n − 1), T(1) = 0. Which count is it?", "a": "n(n − 1)/2: selection sort", "w": ["n log₂ n: merge sort", "n − 1", "2ⁿ"], "why": "The sum of the first n − 1 numbers."}, {"q": "T(n) ≤ T(n/5) + T(7n/10) + cn. Which technique, and what bound?", "a": "shares-below-one: 10cn", "w": ["the master technique: n log n", "shrink-by-one: n²", "guess-and-check: n²"], "why": "The shares add to 9/10, so 1/(1 − 9/10) = 10."}, {"q": "T(n) ≤ T(n/2) + T(n/2) + cn. Does shares-below-one give a linear bound?", "a": "no: the shares add to 1", "w": ["yes", "yes, with K = 2c", "no: the shares add to more than 1"], "why": "It is n log n."}, {"q": "A guess g meets the rule at small sizes, and the rule applied to g gives at most g. Which technique?", "a": "guess-and-check", "w": ["shrink-by-one", "shares-below-one", "the master technique"], "why": "A strong induction."}, {"q": "A check gives Kn + cn from the guess Kn. Is T = O(n) proved?", "a": "no: the check must give at most Kn", "w": ["yes", "yes, with K + c", "no: the guess must be n²"], "why": "The constant would grow at each size."}, {"q": "T(n) = 2T(n/2) + n log₂ n. Its family?", "a": "½ n log₂² n", "w": ["n log₂ n", "n²", "n"], "why": "Each level costs n times the levels left."}, {"q": "T(n) = 7T(n/2) + n². Which wins, and the family?", "a": "the bottom: n^(log₂ 7)", "w": ["the top: n²", "every level equally: n² log n", "the top: n³"], "why": "The master technique, r = 7/4 > 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39n"]=[{"q": "A list that doubles when full takes n puts. Fewer than how many moves in all?", "a": "3n", "w": ["n", "n²", "n log₂ n"], "why": "The doubling-array technique: copies add to less than 2n."}, {"q": "One put into a doubling list holding a million items costs a million moves. Does that break the bound of 3 a put?", "a": "no: the bound is an average", "w": ["yes", "yes, once", "no: copies are free"], "why": "Copies come only at sizes 1, 2, 4, …."}, {"q": "A heap of n items has what height?", "a": "⌊log₂ n⌋", "w": ["n", "√n", "log₂ n + 2"], "why": "The heap-height technique: each level doubles."}, {"q": "In a heap stored by cells, cell i’s children are which cells?", "a": "2i and 2i + 1", "w": ["i + 1 and i + 2", "2i − 1 and 2i", "i/2 and i"], "why": "Each level holds twice the one above."}, {"q": "Is a heap sorted?", "a": "no: only each cell against those below it", "w": ["yes", "yes, row by row", "only its bottom row"], "why": "The bottom row is in no order."}, {"q": "Items added to a search tree in random order: average comparisons in all?", "a": "2(n + 1)Hₙ − 4n", "w": ["n log₂ n exactly", "n(n − 1)/2", "2n"], "why": "The tree-depth technique: the random-pivot count."}, {"q": "Items added to a search tree in sorted order. Its depth?", "a": "n", "w": ["log₂ n", "2 ln n", "√n"], "why": "Each new item goes below the last."}, {"q": "23 keys in 365 slots. The chance some two share?", "a": "about 0.507", "w": ["about 0.063", "about 0.25", "about 0.99"], "why": "The load-share technique’s product."}, {"q": "n keys in m slots. A look for a key that is there checks at most how many on average?", "a": "1 + (n − 1)/m", "w": ["n/m", "log₂ n", "m/n"], "why": "Each other key shares its slot with chance 1/m."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39o"]=[{"q": "The plain program for F(n) = F(n − 1) + F(n − 2) calls itself 2F(n) − 1 times. For n = 40?", "a": "about 205 million calls", "w": ["40 calls", "38 additions", "about 1600 calls"], "why": "C(40) = 204 668 309."}, {"q": "Each answer at a smaller size kept once and reused. Which technique?", "a": "remembered-answers", "w": ["alignment-table", "coin-table", "earliest-finish"], "why": "Cost: the number of sizes times one step."}, {"q": "D(i, j) is the least of D(i − 1, j) + 1, D(i, j − 1) + 1, D(i − 1, j − 1) + 0 or 1. Which technique?", "a": "alignment-table", "w": ["remembered-answers", "coin-table", "load-share"], "why": "The three ways a line-up can end."}, {"q": "The distance of ACGT and AGT?", "a": "1", "w": ["3", "2", "4"], "why": "Drop the C."}, {"q": "Lined up from the left, ACGT and AGT differ in three places. Is their distance 3?", "a": "no: the distance is over every line-up", "w": ["yes", "yes, after dropping T", "no: it is 0"], "why": "The best line-up drops one letter."}, {"q": "Taking again and again the meeting that ends first among those that fit. Which technique?", "a": "earliest-finish", "w": ["coin-table", "remembered-answers", "pivot-chance"], "why": "Greedy never falls behind."}, {"q": "Is taking the shortest meeting first always best?", "a": "no: it can block two meetings", "w": ["yes", "yes, if all meetings are short", "no: it is never best"], "why": "A short meeting across two others costs both."}, {"q": "Coins 1, 3 and 4. Greedy pays 6 with how many coins, and the table?", "a": "greedy 3, the table 2", "w": ["greedy 2, the table 2", "greedy 3, the table 3", "greedy 2, the table 3"], "why": "4 + 1 + 1 against 3 + 3."}, {"q": "The fewest coins for v is 1 plus the least fewest for v − c over coins c ≤ v. Which technique?", "a": "coin-table", "w": ["earliest-finish", "alignment-table", "shrink-by-one"], "why": "Every best way begins with some coin."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39p"]=[{"q": "One both for each row that gives 1, joined by either. Which technique?", "a": "one-row-each", "w": ["neighbour-merge", "two-level-nand", "split-on-one"], "why": "Always right, and large."}, {"q": "The both for the row d r m = 101?", "a": "d ¬r m", "w": ["¬d r ¬m", "d r m", "d ∨ ¬r ∨ m"], "why": "Each input as it is where the row has 1, its not where 0."}, {"q": "x Y ∨ ¬x Y = ?", "a": "Y", "w": ["x", "1", "x Y"], "why": "The neighbour-merge technique, by spreading."}, {"q": "The grid’s columns for two inputs run in which order?", "a": "00, 01, 11, 10", "w": ["00, 01, 10, 11", "00, 10, 01, 11", "11, 10, 01, 00 only"], "why": "Each step across changes one input."}, {"q": "d ¬r m ∨ d r ¬m: do they merge?", "a": "no: they differ in two inputs", "w": ["yes, to d", "yes, to d m", "no: they differ in three inputs"], "why": "Only rows differing in one input merge."}, {"q": "f = m ∨ d ¬r in not-ands. Which form?", "a": "nand(¬m, nand(d, ¬r))", "w": ["nand(m, nand(d, r))", "nand(nand(m, d), ¬r)", "nand(¬m, d ¬r)"], "why": "The two-level-nand technique: a lone input enters as its not."}, {"q": "How many not-ands for m ∨ d ¬r, nots included?", "a": "4", "w": ["3", "5", "16"], "why": "Two nots, the inner gate, the outer gate."}, {"q": "A circuit with no loop is checked by running every row. Which technique?", "a": "circuit-to-table", "w": ["one-row-each", "register-count", "split-on-one"], "why": "Same column, same job."}, {"q": "A block of 3 rows with a 1. Does it merge into one both?", "a": "no: blocks have 2ᵏ rows", "w": ["yes", "yes, if they are neighbours", "no: blocks have 4 rows"], "why": "Three rows are a block of 2 and one more."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["39q"]=[{"q": "i from 1 to n, j from 1 to i: the inner body runs how many times?", "a": "n(n + 1)/2", "w": ["n²", "n", "n(n − 1)"], "why": "The nested-loop technique: 4k’s sum."}, {"q": "Three loops, l ≤ j ≤ i from 1 to n: the body runs how many times?", "a": "n(n + 1)(n + 2)/6", "w": ["n³", "n(n + 1)/2", "n³/3"], "why": "Choices of 3 with repeats allowed."}, {"q": "i doubles from 1 while i ≤ 1000. How many rounds?", "a": "10", "w": ["9", "9.97", "1000"], "why": "1, 2, 4, …, 512: ⌊log₂ 1000⌋ + 1."}, {"q": "k is halved to its whole part while k > 1, from 1000. How many rounds?", "a": "9", "w": ["10", "500", "1000"], "why": "⌊log₂ 1000⌋."}, {"q": "i from 1 to n, j doubling up to i. Family of the count?", "a": "n log n", "w": ["n²", "n", "log n"], "why": "Each inner loop runs ⌊log₂ i⌋ + 1 rounds."}, {"q": "A program calls itself on two halves and loops over n. Its rule?", "a": "T(n) = 2T(n/2) + n", "w": ["T(n) = T(n − 1) + n", "T(n) = 3T(n/2) + n", "T(n) = T(n/2) + 1"], "why": "The call-tree technique: one term a call."}, {"q": "Three calls on halves and a loop over n. Its family?", "a": "n^1.585", "w": ["n log n", "n²", "n"], "why": "The bottom wins: n^(log₂ 3)."}, {"q": "3n² + 100 n log₂ n + 10⁶. Its family?", "a": "O(n²)", "w": ["O(10⁶)", "O(n log n)", "O(n³)"], "why": "The largest-term technique."}, {"q": "3n² + 10⁶: from about which n does 3n² rule?", "a": "578", "w": ["100", "10⁶", "270"], "why": "Below it the start-up term is larger."}];
